const greet = () => "hello";
const tools = { hello: greet, shout: (make) => make().toUpperCase() };

function handBack(fn) {
  return fn;
}

console.log(typeof handBack(greet));
console.log(handBack(greet)());
console.log(tools.shout(greet));
console.log(typeof tools.shout(greet));
console.log(handBack(handBack)(greet) === tools.hello);
